#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/tasks/task_source_projection.hpp"
// 店单尾独立编码冻结授权和实际两腿，旧Task visitor与店铺发行账均不加字段。
#include "task_shop_order_state.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
namespace hanmo::resident {namespace {
template<class A>Status private_owner(A& a,Owner& o){if(o.extra)return a.reject("TaskShopOrderOwnerMetadataUnsupported");dynamic_codec::enumeration(a,"kind",o.kind,1);return a.field("id",o.id);}
template<class A>Status terms(A& a,PrivateShopOrderTerms& t){a.field("order_id",t.order_id);a.field("shop_id",t.shop_id);a.field("proprietor_actor_id",t.proprietor_actor_id);a.object("original_client",[&](auto& c){return private_owner(c,t.original_client);});a.field("task_template_id",t.task_template_id);a.field("item_id",t.item_id);a.field("stock_inventory_id",t.stock_inventory_id);a.field("shop_wallet_id",t.shop_wallet_id);a.field("client_inventory_id",t.client_inventory_id);a.field("client_wallet_id",t.client_wallet_id);a.field("quantity",t.quantity);a.field("contract_price",t.contract_price);a.field("accepted_tick",t.accepted_tick);return a.field("deadline_tick",t.deadline_tick);}
template<class A>Status binding(A& a,TaskShopOrderBinding& b){a.field("fact_id",b.fact_id);a.field("task_id",b.task_id);a.field("order_id",b.order_id);a.field("order_issue_fact_id",b.order_issue_fact_id);a.field("reservation_id",b.reservation_id);return a.object("terms",[&](auto& c){return terms(c,b.terms);});}
template<class A>Status lot(A& a,TaskShopOrderLotLeg& l){a.field("item_id",l.item_id);a.field("source_lot_id",l.source_lot_id);a.field("destination_lot_id",l.destination_lot_id);a.object("source_owner",[&](auto& c){return private_owner(c,l.source_owner);});a.object("destination_owner",[&](auto& c){return private_owner(c,l.destination_owner);});a.field("quantity",l.quantity);a.field("source_before",l.source_before);return a.field("source_after",l.source_after);}
template<class A>Status settlement(A& a,TaskShopOrderSettlement& s){a.field("fact_id",s.fact_id);a.field("task_id",s.task_id);a.field("order_id",s.order_id);a.field("source_action_id",s.source_action_id);a.field("settlement_id",s.settlement_id);a.field("outcome",s.outcome);a.field("termination",s.termination);a.field("from_inventory_id",s.from_inventory_id);a.field("to_inventory_id",s.to_inventory_id);a.field("from_wallet_id",s.from_wallet_id);a.field("to_wallet_id",s.to_wallet_id);a.object("from_container_owner",[&](auto& c){return private_owner(c,s.from_container_owner);});a.object("to_container_owner",[&](auto& c){return private_owner(c,s.to_container_owner);});a.field("tick",s.tick);a.field("action_started_tick",s.action_started_tick);a.field("delivered_quantity",s.delivered_quantity);a.field("paid_price",s.paid_price);a.field("refunded_price",s.refunded_price);return a.sequence("lots",s.lots,[](auto& c,auto& row){return lot(c,row);});}
template<class A>Status action(A& a,TaskShopOrderAction& x){if(x.context.kind||x.context.encounter_id||x.context.input_error)return a.reject("UnsupportedTaskShopOrderContext");a.field("action_id",x.action_id);a.field("task_id",x.task_id);a.object("context",[&](auto& c){c.field("place_id",x.context.place_id);c.field("provider_actor_id",x.context.provider_actor_id);return c.field("role_id",x.context.role_id);});a.field("session_id",x.session_id);a.field("dialogue_id",x.dialogue_id);a.field("node_id",x.node_id);return a.field("started_tick",x.started_tick);}
template<class A>Status interruption(A& a,TaskShopOrderInterruption& x){a.field("fact_id",x.fact_id);a.object("source",[&](auto& c){return action(c,x.source);});a.field("tick",x.tick);return a.field("code",x.code);}
template<class A>Status state(A& a,TaskShopOrderState& s){a.field("version",s.version);if(s.version!=1)return a.reject("UnsupportedTaskShopOrderVersion");auto r=dynamic_codec::table(a,"bindings",s.bindings,[](auto& c,auto& row){return binding(c,row);});if(!r.ok)return r;r=dynamic_codec::table(a,"settlements",s.settlements,[](auto& c,auto& row){return settlement(c,row);});if(!r.ok)return r;r=dynamic_codec::table(a,"actions",s.actions,[](auto& c,auto& row){return action(c,row);});if(!r.ok)return r;return dynamic_codec::table(a,"interruptions",s.interruptions,[](auto& c,auto& row){return interruption(c,row);});}
Status unique(const BoundaryValue& v,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("TaskShopOrderTooDeep");if(const auto* fields=v.as<BoundaryValue::Dict>()){if(fields->size()>CodecVisitor::max_items)return common_failure("TaskShopOrderTooLarge");std::set<StableId> seen;for(const auto& row:*fields){if(!seen.insert(row.first).second)return common_failure("DuplicateTaskShopOrderField",row.first);auto valid=unique(row.second,depth+1);if(!valid.ok)return valid;}}if(const auto* rows=v.as<BoundaryValue::Array>()){if(rows->size()>CodecVisitor::max_items)return common_failure("TaskShopOrderTooLarge");for(const auto& row:*rows){auto valid=unique(row,depth+1);if(!valid.ok)return valid;}}return common_success();}
}
Outcome<TaskShopOrderAction> decode_task_shop_order_action(const BoundaryValue& v){auto valid=unique(v);if(!valid.ok)return {false,{},valid.error};TaskShopOrderAction result;dynamic_codec::JsonArchive a(v);valid=action(a,result);if(valid.ok)valid=a.finish();if(!valid.ok)return {false,{},valid.error};return {true,std::move(result),{}};}
Status emit_task_shop_order_action_fields(ProjectionWriter&w,const TaskShopOrderAction&v){dynamic_projection::Archive a(w);return action(a,const_cast<TaskShopOrderAction&>(v));}
BoundaryValue encode_task_shop_order_action(const TaskShopOrderAction& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_task_shop_order_action_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
void rebuild_task_shop_order_index(TaskShopOrderState& s){s.by_proprietor.clear();s.by_order.clear();s.by_task.clear();for(const auto& row:s.bindings.rows()){s.by_proprietor[row.second.terms.proprietor_actor_id].push_back(row.first);s.by_order.emplace(row.second.order_id,row.first);s.by_task.emplace(row.second.task_id,row.first);}}
Outcome<TaskShopOrderState> decode_task_shop_orders(const BoundaryValue& v){auto valid=unique(v);if(!valid.ok)return {false,{},valid.error};TaskShopOrderState result;dynamic_codec::JsonArchive a(v);valid=state(a,result);if(valid.ok)valid=a.finish();if(!valid.ok)return {false,{},valid.error};rebuild_task_shop_order_index(result);return {true,std::move(result),{}};}
Status emit_task_shop_orders_fields(ProjectionWriter&w,const TaskShopOrderState&v){dynamic_projection::Archive a(w);return state(a,const_cast<TaskShopOrderState&>(v));}
BoundaryValue encode_task_shop_orders(const TaskShopOrderState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_task_shop_orders_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Status visit_task_shop_orders_checkpoint(CodecVisitor& a,TaskShopOrderState& s){auto result=state(a,s);if(result.ok&&a.reading())rebuild_task_shop_order_index(s);return result;}
Status emit_task_shop_order_binding_fields(ProjectionWriter&w,const TaskShopOrderBinding&v){dynamic_projection::Archive a(w);return binding(a,const_cast<TaskShopOrderBinding&>(v));}

Status emit_task_shop_order_settlement_fields(ProjectionWriter&w,const TaskShopOrderSettlement&v){dynamic_projection::Archive a(w);return settlement(a,const_cast<TaskShopOrderSettlement&>(v));}

Status emit_task_shop_order_interruption_fields(ProjectionWriter&w,const TaskShopOrderInterruption&v){dynamic_projection::Archive a(w);return interruption(a,const_cast<TaskShopOrderInterruption&>(v));}

}
